using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities to the research agent.
/// Uses a simulated search for demonstration; replace with a real search API (e.g., Bing Search) in production.
/// </summary>
public static class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        // In production, replace this with a real search API call (e.g., Bing Web Search API).
        // This simulation demonstrates the tool interface the agent uses.
        var results = new List<object>();

        for (int i = 1; i <= Math.Min(maxResults, 5); i++)
        {
            results.Add(new
            {
                title = $"Result {i} for: {query}",
                snippet = $"This is a simulated search result snippet #{i} related to '{query}'. " +
                          $"In production, this would contain real web content from a search API.",
                url = $"https://example.com/search/{Uri.EscapeDataString(query)}/result{i}"
            });
        }

        return JsonSerializer.Serialize(new
        {
            query,
            resultCount = results.Count,
            results
        }, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities for the research agent to organize findings.
/// </summary>
public static class NoteTakingTool
{
    private static readonly List<Note> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record key findings during research.")]
    public static string SaveNote(
        [Description("A short title summarizing the note")] string title,
        [Description("The detailed content of the note")] string content)
    {
        var note = new Note(title, content, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note saved: '{title}' (total notes: {_notes.Count})";
    }

    [Description("Retrieves all saved research notes to review findings before summarizing.")]
    public static string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");

        for (int i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"\n--- Note {i + 1}: {note.Title} ---");
            sb.AppendLine($"Recorded: {note.Timestamp:u}");
            sb.AppendLine(note.Content);
        }

        return sb.ToString();
    }

    public static void Clear() => _notes.Clear();

    private sealed record Note(string Title, string Content, DateTime Timestamp);
}

