using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

// Load configuration
var configuration = new ConfigurationBuilder()
    .AddJsonFile("appsettings.json", optional: true)
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

// Build the chat client with the MEAI abstraction
IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .Build();

// Define tools available to the agent
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(NoteTakingTool.SaveNote),
    AIFunctionFactory.Create(NoteTakingTool.GetAllNotes),
};

// Create the research agent using Microsoft Agent Framework
var researchAgent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using multiple queries
        2. Taking notes on key findings as you discover them
        3. Reviewing all your notes at the end
        4. Providing a comprehensive summary of your research

        Always search for at least 2-3 different aspects of the topic.
        Save a note for each important finding.
        After gathering enough information, retrieve all notes and synthesize a final summary.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and organizing findings into notes.",
    tools: tools);

// Get the research topic
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine() ?? "artificial intelligence";
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('─', 50));

// Run the agent with iteration limits and cost controls
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await researchAgent.RunAsync(
    $"Please research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

// Display the final response
Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('─', 50));

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 })
    {
        Console.WriteLine(message.Text);
    }
}

